/******************************************************************************
 * @file            ld.h
 *****************************************************************************/
#ifndef     _LD_H
#define     _LD_H

#define     FAKE_LD_FILENAME            "autogenerated"

struct ld_state {

    const char **input_files;
    long nb_input_files;
    
    const char *entry_symbol_name;
    unsigned long entry_point;
    
    const char *output_map_filename;
    unsigned long base_address;
    
    const char *output_filename;
    int create_shared_library, format;
    
    int emit_relocs, use_custom_base_address;
    unsigned long size_of_headers;
    
    int generate_symbols_table;

};

#define     LD_FORMAT_COM               0x00
#define     LD_FORMAT_MZ                0x01
#define     LD_FORMAT_BIN               0x02

#define     LD_FORMAT_IA16_ELKS         0x03
#define     LD_FORMAT_I386_ELKS         0x04

#define     LD_FORMAT_I386_AOUT         0x05
#define     LD_FORMAT_I386_COFF         0x06

#define     LD_FORMAT_I386_PE           0x07

extern struct ld_state *state;
extern const char *program_name;

void map_write (const char *filename);
void link (void);

#endif      /* _LD_H */
